SET ten_khach_san = 'Grand Saigon Hotel',
    dia_chi = '123 Nguyễn Huệ, Quận 1, TP. Hồ Chí Minh',
    so_dien_thoai = '1900 1234',
    email = 'booking@grandsaigon.vn',
    mo_ta = 'Nghỉ dưỡng đẳng cấp giữa lòng thành phố.'
